<!-- This file is generated by AI. -->

<!--
  参考音频列表编辑器 (搜索 + 列表 + 添加), 「编辑角色」与「选择参考音频」共用。

  两处**本来就是同一件事** (看一个角色的参考音频, 挑一条, 或者补一条), 因此必须共用这一个
  组件: 拆成两套实现时同一个动作会长得不一样 —— 一个有搜索框一个没有, 一个加完就退出
  一个留在原地。共享之后它们在结构上不可能再分叉。

  交互约定: 「添加参考音频」走同一个 `AddReferenceDialog`, **加完就地刷新列表、父对话框不退出**
  (补齐一个角色的语料往往要连着加好几条); 选择器场景 (`onPick` 存在) 里点条目即选中并交给调用方;
  收藏用星标 (与「选择角色」里给角色加星同一套交互), 收藏的条目排在前面, 并成为该角色的
  默认参考音频; 除参考音频的选择与收藏外没有批量操作。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { voiceRemoveReference, type Character, type ReferenceAudio } from '../commands/voice';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { errorSummary } from '../voice/errorText';
  import { LANGUAGE_LABELS, sortReferences } from '../voice/types';
  import AddReferenceDialog from './AddReferenceDialog.svelte';
  import Button from './Button.svelte';
  import TakePlayer from './TakePlayer.svelte';

  let {
    character,
    /** 选择器场景: 当前选中的参考音频 (高亮显示) */
    selectedHash = null,
    /** 选择器场景: 点条目即选中。不传表示只做编辑 (编辑角色对话框) */
    onPick,
    /**
     * 选择器场景: 刚添加了一条。
     *
     * 与 `onPick` 分开是必要的: 点条目意味着"选好了" (可以关掉对话框), 而"又加了一条"
     * 往往只是批量补语料的第一步, 对话框要留在原地。
     */
    onAdded,
    /** 列表内容已变化 (增删), 调用方据此刷新自己持有的角色快照 */
    onChanged,
  }: {
    character: Character;
    selectedHash?: string | null;
    onPick?: (hash: string) => void;
    onAdded?: (hash: string) => void;
    onChanged: () => void;
  } = $props();

  let query = $state('');
  let addOpen = $state(false);
  let busy = $state(false);
  let error = $state<string | null>(null);

  /*
   * 换角色时清空搜索与报错 (它们都属于"上一个角色"的上下文)。
   * 只比较 id: 同一个角色的引用列表变化不该把用户正在敲的搜索词清掉。
   */
  let lastCharacterId = '';
  $effect(() => {
    const id = character.id;
    if (id === lastCharacterId) return;
    lastCharacterId = id;
    query = '';
    error = null;
  });

  const references = $derived.by(() => {
    // 收藏优先 (与角色列表的星标同一套排序); 搜索只过滤, 不改变已定的顺序
    const list = sortReferences(character.references);
    const needle = query.trim().toLowerCase();
    if (!needle) return list;
    return list.filter(
      (reference) =>
        reference.text.toLowerCase().includes(needle) ||
        reference.tags.some((tag) => tag.toLowerCase().includes(needle))
    );
  });

  const total = $derived(character.references.length);

  /**
   * 收藏 / 取消收藏。
   *
   * 收藏既是排序依据, 也是"没有显式选择时用哪条参考音频"的默认值 —— 只改排序而不改
   * 默认选择的话, 这个标记对实际生成毫无影响。
   */
  async function toggleStarred(reference: ReferenceAudio): Promise<void> {
    busy = true;
    error = null;
    try {
      await voiceController.updateReference(character.id, reference.hash, { starred: !reference.starred });
      onChanged();
    } catch (caught) {
      error = errorSummary(String(caught));
    } finally {
      busy = false;
    }
  }

  async function removeReference(reference: ReferenceAudio): Promise<void> {
    busy = true;
    error = null;
    try {
      const updated = await voiceRemoveReference(character.id, reference.hash);
      voiceController.setCharacters(appStore.voiceCharacters.map((item) => (item.id === updated.id ? updated : item)));
      onChanged();
    } catch (caught) {
      error = errorSummary(String(caught));
    } finally {
      busy = false;
    }
  }
</script>

<div class="reference-editor">
  <div class="dialog-toolbar">
    <input class="ui-input dialog-toolbar-grow" placeholder="搜索参考文本或标签…" bind:value={query} />
    <!-- 计数放在搜索框与按钮之间: 搜索时显示"匹配 N / 共 M", 平时只显示总数 -->
    <span class="reference-count">
      {query.trim() ? `匹配 ${references.length} / 共 ${total}` : `共 ${total} 条`}
    </span>
    <Button appearance="primary" icon="Add" disabled={busy} onclick={() => (addOpen = true)}>添加参考音频</Button>
  </div>

  <div class="reference-list dialog-scroll">
    {#if total === 0}
      <p class="voice-dialog-empty">还没有参考音频。参考文本必须与音频逐字一致, 时长 3~10 秒。</p>
    {/if}
    {#if total > 0 && references.length === 0}
      <p class="voice-dialog-empty">没有匹配的参考音频。</p>
    {/if}
    {#each references as reference (reference.hash)}
      <div class="reference-item" class:selected={reference.hash === selectedHash}>
        <!--
          条目主体: 选择器场景里是按钮 (点一下就用这条), 编辑角色里只是说明文字。两种场景
          渲染成不同元素, 而不是同一个按钮加 disabled —— 后者会带上一套"不可用"的灰化样式。
        -->
        {#if onPick}
          <button
            type="button"
            class="reference-main"
            title="使用这条参考音频"
            onclick={() => onPick?.(reference.hash)}
          >
            <span class="reference-text">{reference.text || '（未填写参考文本）'}</span>
            <span class="reference-meta">
              {LANGUAGE_LABELS[reference.language] ?? reference.language} · {reference.duration.toFixed(2)}s ·
              {Math.round(reference.sampleRate / 1000)}kHz{#if reference.tags.length > 0}
                · {reference.tags.join(' / ')}{/if}
            </span>
          </button>
        {:else}
          <div class="reference-main reference-main-static">
            <span class="reference-text">{reference.text || '（未填写参考文本）'}</span>
            <span class="reference-meta">
              {LANGUAGE_LABELS[reference.language] ?? reference.language} · {reference.duration.toFixed(2)}s ·
              {Math.round(reference.sampleRate / 1000)}kHz{#if reference.tags.length > 0}
                · {reference.tags.join(' / ')}{/if}
            </span>
          </div>
        {/if}

        <Button
          appearance="bare"
          className={reference.starred ? 'reference-star starred' : 'reference-star'}
          icon={reference.starred ? 'StarFilled' : 'Star'}
          title={reference.starred ? '取消收藏' : '收藏（收藏的参考音频靠前，并作为默认参考音频）'}
          disabled={busy}
          onclick={() => void toggleStarred(reference)}
        />

        <TakePlayer
          path={voiceController.referencePathFor(character.id, reference.file)}
          key={`ref:${reference.hash}`}
        />
        <Button
          appearance="bare"
          className="danger-icon"
          icon="Delete"
          title="删除该参考音频"
          disabled={busy}
          onclick={() => void removeReference(reference)}
        />
      </div>
    {/each}
  </div>

  {#if error}
    <p class="voice-error">{error}</p>
  {/if}

  {#if addOpen}
    <AddReferenceDialog
      {character}
      onClose={() => (addOpen = false)}
      onAdded={(added) => {
        // 加完留在原地 (只关掉添加对话框): 刷新列表, 选择器场景把新条目设为当前项
        onChanged();
        onAdded?.(added.hash);
      }}
    />
  {/if}
</div>
